-- Seed data para competencias específicas de 3er Grado del Nivel Secundario
-- Documento oficial: Adecuación Curricular Nivel Secundario - Primer Ciclo (3er Grado)

INSERT INTO public.curr_competencias_especificas (nivel, grado, asignatura, bloque, competencia_fundamental, codigo, descriptor) VALUES
-- Lengua Española
('Secundaria', '3ro', 'Lengua Española', 'BC1', 'Comunicativa', 'CE-LE1', 'Demuestra dominio, desenvolvimiento y creatividad al comunicarse eficazmente de manera personal y colectiva en su entorno familiar, escolar y de la comunidad, utilizando un género textual (funcional o literario), a partir de la comprensión y producción oral y escrita, la utilización responsable de las TIC y demás medios.'),
('Secundaria', '3ro', 'Lengua Española', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LE2', 'Demuestra la validez de las informaciones sostenidas en los juicios, puntos de vista, conclusiones, acciones y pensamientos que construye, usando un género textual que respete la diversidad de opiniones.'),
('Secundaria', '3ro', 'Lengua Española', 'BC2', 'Resolución de Problemas', 'CE-LE3', 'Presenta resultados de investigaciones a través de textos específicos, orales y escritos, como ensayos o informes, que evidencian la solución de problemas en contextos determinados, con una postura de criticidad, valoración y respeto a los datos citados.'),
('Secundaria', '3ro', 'Lengua Española', 'BC4', 'Ética y Ciudadana', 'CE-LE4', 'Produce textos en la elaboración de proyectos encaminados a la construcción de una ciudadanía responsable, abierta e inclusiva que busca soluciones colectivas a los problemas sociales.'),
('Secundaria', '3ro', 'Lengua Española', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LE7', 'Valora y promueve el uso de la lengua oral y escrita al realizar lecturas y escrituras reflexivas, canalizando emociones y sentimientos, hacia el fortalecimiento de las relaciones humanas y el respeto a la dignidad.'),
('Secundaria', '3ro', 'Lengua Española', 'BC3', 'Científica y Tecnológica', 'CE-LE5', 'Expone investigaciones científicas sencillas que realiza, apoyándose en el uso de textos de secuencia expositivo-explicativa en actos de intercomunicación que se desarrollan en la escuela y otros contextos, tomando en cuenta su conocimiento en la utilización de variadas herramientas tecnológicas con que cuenta.'),
('Secundaria', '3ro', 'Lengua Española', 'BC3', 'Ambiental y de la Salud', 'CE-LE6', 'Promueve comportamientos y valores sobre la conservación de la salud, de la naturaleza y sus ecosistemas, mediante el uso de textos variados y a través del desarrollo de actividades de intercomunicación en diferentes contextos de la comunidad.'),

-- Lenguas Extranjeras - Inglés
('Secundaria', '3ro', 'Inglés', 'BC1', 'Comunicativa', 'CE-LEI1', 'Comprende y expresa ideas, sentimientos y valores culturales en distintas situaciones de comunicación concretas sobre temas cotidianos, utilizando el idioma inglés para explicar, sugerir, hacer prohibiciones y advertencias, dar instrucciones, dar noticias, secuenciar eventos, inferir, predecir y comparar.'),
('Secundaria', '3ro', 'Inglés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEI2', 'Se comunica en el idioma inglés breve y sencillo en forma oral y escrita, mediante el razonamiento y la reflexión lógico-verbal con el propósito de estructurar mensajes coherentes que presenta de una forma creativa, ejerciendo su pensamiento analítico.'),
('Secundaria', '3ro', 'Inglés', 'BC2', 'Resolución de Problemas', 'CE-LEI3', 'Interactúa en inglés con el propósito de expresar opiniones, explicaciones y predicciones, así como dar sugerencias, indicaciones e instrucciones ante diversas circunstancias de su entorno inmediato, empleando estrategias de desempeño oral y escrito que permiten comprenderse con escucha y lectura atenta de su interlocutor.'),
('Secundaria', '3ro', 'Inglés', 'BC4', 'Ética y Ciudadana', 'CE-LEI4', 'Se comunica de forma oral y escrita en el idioma inglés, participando con cortesía y respeto en intercambios sencillos, valorando las diferencias individuales y la identidad social y cultural básicas, propias de la cultura local y global.'),
('Secundaria', '3ro', 'Inglés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEI7', 'Se comunica en el idioma inglés, con cortesía, honestidad, actitud de respeto y aceptación al compartir información y expresar puntos de vista sobre hechos e informaciones que le son conocidas y de su interés.'),
('Secundaria', '3ro', 'Inglés', 'BC3', 'Científica y Tecnológica', 'CE-LEI5', 'Interactúa en el idioma inglés con el propósito de solicitar y ofrecer explicaciones, opinar, dar instrucciones y dar noticias sobre asuntos científicos, tecnológicos y de otra índole, en distintas situaciones de comunicación.'),
('Secundaria', '3ro', 'Inglés', 'BC3', 'Ambiental y de la Salud', 'CE-LEI6', 'Muestra inclinación por estilos de vida saludables y cuidado del medio ambiente al interactuar en distintas situaciones de comunicación en el idioma inglés, donde se intercambia información sobre indicaciones, prohibiciones, advertencias, opiniones y sugerencias.'),

-- Lenguas Extranjeras - Francés
('Secundaria', '3ro', 'Francés', 'BC1', 'Comunicativa', 'CE-LEF1', 'Se comunica en francés oral y escrito, utilizando frases y oraciones básicas, breves y sencillas, previamente ensayadas, referentes a temas cotidianos en situaciones inmediatas comunicativas, donde indica la ubicación, describe las condiciones atmosféricas, y las actividades que se llevan cabo en planes futuros.'),
('Secundaria', '3ro', 'Francés', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-LEF2', 'Se comunica en el idioma francés, utilizando la lógica verbal para estructurar un repertorio creciente de frases y expresiones breves y sencillas que ensaya y presenta en distintas situaciones inmediatas de comunicación de forma creativa previamente planificada, necesitando ayuda al expresarse y esfuerzo para ser comprendido.'),
('Secundaria', '3ro', 'Francés', 'BC2', 'Resolución de Problemas', 'CE-LEF3', 'Comprende y expresa informaciones relevantes para resolver situaciones y problemas de su entorno cotidiano y necesidades inmediatas de comunicación, tales como la descripción de sí mismo, personas, lugares, objetos, condiciones atmosféricas y planes futuros, utilizando frases hechas y oraciones muy breves y sencillas, con la ayuda de su interlocutor para poder expresarse y poder ser comprendido.'),
('Secundaria', '3ro', 'Francés', 'BC4', 'Ética y Ciudadana', 'CE-LEF4', 'Se comunica de forma oral y escrita, con cortesía, respeto y asertividad, en intercambios muy sencillos en francés, identificando las diferencias individuales y la identidad social y cultural propia y de otros países y detalles de información personal relativas a actividades cotidianas, medios de transporte, lugares, clima y planes futuros.'),
('Secundaria', '3ro', 'Francés', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-LEF7', 'Interactúa con otras personas en el idioma francés, con cortesía actitud de respeto, honestidad y aceptación, al compartir informaciones, describir actividades cotidianas y planes, objetos de su pertenencia, lugares y condiciones atmosféricas de su comunidad.'),
('Secundaria', '3ro', 'Francés', 'BC3', 'Científica y Tecnológica', 'CE-LEF5', 'Reconoce, organiza y comparte en formato físico, digital o en línea, información relativa a la ciencia y la tecnología presentes en su entorno cotidiano, utilizando un vocabulario ensayado que requiere de mínimo esfuerzo para ser comprendido.'),
('Secundaria', '3ro', 'Francés', 'BC3', 'Ambiental y de la Salud', 'CE-LEF6', 'Interactúa mostrando preferencia por opciones que impactan positivamente la salud y el medio ambiente, en distintas situaciones inmediatas de comunicación oral y escrita, donde identifica y describe actividades que realiza, sus planes y las condiciones del entorno.'),

-- Matemática
('Secundaria', '3ro', 'Matemática', 'BC1', 'Comunicativa', 'CE-MAT1', 'Evalúa ideas matemáticas utilizando para su interpretación las destrezas de leer, escuchar y visualizar.'),
('Secundaria', '3ro', 'Matemática', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-MAT2', 'Evalúa conjeturas y argumentos matemáticos para dar validez a sus propias ideas sobre temas del área y de otras disciplinas.'),
('Secundaria', '3ro', 'Matemática', 'BC2', 'Resolución de Problemas', 'CE-MAT3', 'Genera soluciones y estrategias en situaciones de problemas nuevos, de pasos múltiples y no rutinarias en las diferentes áreas de la matemática y fuera de ésta.'),
('Secundaria', '3ro', 'Matemática', 'BC4', 'Ética y Ciudadana', 'CE-MAT4', 'Genera ideas y opciones creativas en el trabajo colaborativo para la búsqueda de soluciones a situaciones que impliquen conocimientos matemáticos.'),
('Secundaria', '3ro', 'Matemática', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-MAT7', 'Muestra actitud crítica en la búsqueda de soluciones a situaciones relacionadas con el quehacer matemático, respetando los diferentes puntos de vistas de sus compañeros.'),
('Secundaria', '3ro', 'Matemática', 'BC3', 'Científica y Tecnológica', 'CE-MAT5', 'Analiza discriminando la pertinencia de diferentes tipos de herramientas tecnológicas para la resolución de problemas matemáticos en situaciones del entorno.'),
('Secundaria', '3ro', 'Matemática', 'BC3', 'Ambiental y de la Salud', 'CE-MAT6', 'Analiza problemas relacionados con la salud y el medioambiente para la comprensión de los modelos matemáticos empleados en su solución.'),

-- Ciencias Sociales
('Secundaria', '3ro', 'Ciencias Sociales', 'BC1', 'Comunicativa', 'CE-CS1', 'Demuestra en sus proyectos de investigación respeto por la autoría de las fuentes primaria y secundaria consultadas sobre procesos sociales, políticos, económicos, históricos, geográficos o culturales, con la finalidad de avalar la originalidad y credibilidad de sus informaciones.'),
('Secundaria', '3ro', 'Ciencias Sociales', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CS2', 'Comprende las relaciones geopolíticas entre las diferentes naciones y regiones a lo largo de la historia, así como los cambios ocurridos por los factores geográficos, con la finalidad de fomentar el desarrollo del pensamiento crítico y el análisis de informaciones en el tiempo y el espacio.'),
('Secundaria', '3ro', 'Ciencias Sociales', 'BC2', 'Resolución de Problemas', 'CE-CS3', 'Aplica procedimientos científicos en el levantamiento de informaciones para solucionar un problema, con la finalidad de comprobar su impacto en el tiempo y en el espacio.'),
('Secundaria', '3ro', 'Ciencias Sociales', 'BC4', 'Ética y Ciudadana', 'CE-CS4', 'Incorpora en su proyectos e investigaciones, estrategias que propicien la cultura de paz y el respeto por los valores culturales e interculturales; con la finalidad de promover una convivencia democrática y el respeto a los derechos humanos.'),
('Secundaria', '3ro', 'Ciencias Sociales', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CS7', 'Promueve la empatía y la comprensión a través de relaciones armoniosas y equilibradas, con la finalidad de contribuir en la formación de una ciudadanía responsable y el fomento de prácticas democráticas.'),
('Secundaria', '3ro', 'Ciencias Sociales', 'BC3', 'Científica y Tecnológica', 'CE-CS5', 'Aplica el método científico al realizar explicaciones de fenómenos naturales y sociales en sus investigaciones y proyectos, con la finalidad de comprobar la validez de las teorías que las sustentan.'),
('Secundaria', '3ro', 'Ciencias Sociales', 'BC3', 'Ambiental y de la Salud', 'CE-CS6', 'Verifica en propuestas y proyectos de investigación el impacto de la acción humana sobre la salud y el medioambiente, con la finalidad de presentar posibles soluciones a estas problemáticas.'),

-- Ciencias de la Naturaleza – Ciencias Físicas
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC1', 'Comunicativa', 'CE-CN1', 'Se comunica utilizando el lenguaje científico y tecnológico de ciencias físicas, al expresar sus ideas básicas en respuestas a preguntas y situaciones de problemas simulados y reales.'),
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-CN2', 'Ofrece explicaciones científicas y tecnológicas a problemas y fenómenos naturales relacionados a Ciencias Físicas.'),
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC2', 'Resolución de Problemas', 'CE-CN3', 'Aplica procedimientos científicos y tecnológicos, básicos y organizados para solucionar problemas o dar respuestas a fenómenos naturales relacionados con Ciencias Físicas.'),
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC4', 'Ética y Ciudadana', 'CE-CN4', 'Analiza la naturaleza de las ciencias naturales y el alcance del desarrollo tecnológico en nuestra sociedad relacionada con Ciencias Físicas, sus aportes y reflexiones éticos.'),
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-CN7', 'Gestiona actitudes intelectuales, emocionales y conductuales proactivas al desarrollo de su proyección personal desde las Ciencias Físicas.'),
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC3', 'Científica y Tecnológica', 'CE-CN5', 'Se cuestiona e identifica problemas y situaciones, y les da explicación, utilizando ideas y procesos fundamentales de las Ciencias Físicas y las ingenierías, así como recurso las TIC.'),
('Secundaria', '3ro', 'Ciencias de la Naturaleza', 'BC3', 'Ambiental y de la Salud', 'CE-CN6', 'Actúa con responsabilidad crítica y autónoma, para el cuidado de su salud y ambiental relacionada con Ciencias Físicas.'),

-- Educación Artística
('Secundaria', '3ro', 'Educación Artística', 'BC1', 'Comunicativa', 'CE-EA1', 'Realiza producciones artísticas incorporando aspectos fundamentales de los lenguajes artísticos y del contexto planteado por las ideas y épocas, difundiendo sus creaciones.'),
('Secundaria', '3ro', 'Educación Artística', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EA2', 'Emprende proyectos artísticos colectivos, valorando críticamente las distintas manifestaciones integradas, al identificar sus componentes y reconocer su trascendencia.'),
('Secundaria', '3ro', 'Educación Artística', 'BC2', 'Resolución de Problemas', 'CE-EA3', 'Realiza producciones incorporando aspectos fundamentales de los lenguajes artísticos y del contexto planteado por las ideas y épocas, difundiendo sus creaciones.'),
('Secundaria', '3ro', 'Educación Artística', 'BC4', 'Ética y Ciudadana', 'CE-EA4', 'Emprende proyectos artísticos colectivos que tengan un impacto social o cultural, a partir del análisis del arte popular como fruto de la necesidad de comunicación de los pueblos.'),
('Secundaria', '3ro', 'Educación Artística', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EA7', 'Incorpora valores en sus interpretaciones y creaciones, utilizando lenguajes artísticos y considerando aspectos de su contexto.'),
('Secundaria', '3ro', 'Educación Artística', 'BC3', 'Científica y Tecnológica', 'CE-EA5', 'Analiza los recursos tecnológicos como protagonistas y mediadores de las tramas, los ambientes y los espacios creados en producciones artísticas.'),
('Secundaria', '3ro', 'Educación Artística', 'BC3', 'Ambiental y de la Salud', 'CE-EA6', 'Promueve el uso adecuado de recursos al crear o valorar en el arte técnicas de reúso, reducción y reciclaje de materiales de desecho y cuidado de los ambientes.'),

-- Educación Física
('Secundaria', '3ro', 'Educación Física', 'BC1', 'Comunicativa', 'CE-EF1', 'Muestra dominio motriz en la utilización de su cuerpo para expresar sentimientos, emociones y estados de ánimo en relación armónica con las demás personas y su entorno social y cultural.'),
('Secundaria', '3ro', 'Educación Física', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-EF2', 'Muestra dominio eficaz de su acción motriz individual y grupal, como resultante de su percepción y apreciación de patrones, tamaños, formas, direcciones y relaciones espaciales y temporales en diversos entornos, a partir de la noción de su esquema corporal.'),
('Secundaria', '3ro', 'Educación Física', 'BC2', 'Resolución de Problemas', 'CE-EF3', 'Muestra dominio del perímetro de juego y de las características de sus distintos implementos, con el fin de lograr niveles adecuados de desempeño motriz en juegos y deportes, a partir de sus condiciones Físicas naturales permitiéndole alcanzar eficacia motora progresiva.'),
('Secundaria', '3ro', 'Educación Física', 'BC4', 'Ética y Ciudadana', 'CE-EF4', 'Se relaciona con los demás, con respeto y responsabilidad, en la realización de acciones motrices diversas, a fin de reconocer sus diferencias y similitudes y considerarse parte de un grupo.'),
('Secundaria', '3ro', 'Educación Física', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-EF7', 'Utiliza sus habilidades motrices y capacidades físicas en la realización de tareas acorde con su desarrollo corporal, a los fines de alcanzar las metas en el juego a la vez que disfruta de este.'),
('Secundaria', '3ro', 'Educación Física', 'BC3', 'Científica y Tecnológica', 'CE-EF5', 'Aplica distintos niveles de su capacidad motora con base en sus condiciones físicas naturales para lograr un desempeño motriz eficaz en diversas situaciones de juegos, deportes, trabajo y de la vida cotidiana.'),
('Secundaria', '3ro', 'Educación Física', 'BC3', 'Ambiental y de la Salud', 'CE-EF6', 'Interpreta los cambios físicos que le permite el dominio corporal y la eficiencia motora, con el fin de establecer una relación armónica, saludable y creativa con el espacio que lo rodea y con las demás personas.'),

-- Formación Integral Humana y Religiosa
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC1', 'Comunicativa', 'CE-FIHR1', 'Promueve el valor de la vida a partir de los derechos humanos, las enseñanzas del cristianismo y de otras concepciones religiosas en sus relaciones interpersonales.'),
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC2', 'Pensamiento Lógico, Creativo y Crítico', 'CE-FIHR2', 'Analiza las habilidades, actitudes, características, talentos, intereses y valores vinculados al mundo laboral, a fin de ir visualizando su proyecto de vida en la sociedad.'),
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC2', 'Resolución de Problemas', 'CE-FIHR3', 'Fomenta la resolución y prevención de conflictos interpersonales, basado en el diálogo y la escucha, a fin de propiciar la convivencia armónica en su familia, la escuela y la sociedad.'),
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC4', 'Ética y Ciudadana', 'CE-FIHR4', 'Plantea la forma en que los valores practicados por Jesús de Nazaret están presentes en el contexto sociocultural dominicano, a fin de incorporarlos en su relación con las demás personas.'),
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC4', 'Desarrollo Personal y Espiritual', 'CE-FIHR7', 'Responde a las interrogantes que surgen en la etapa de la adolescencia mediante el cultivo de valores humanos, morales, éticos y religiosos, con la finalidad de actuar de forma apropiada en su familia, la escuela y la comunidad.'),
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC3', 'Científica y Tecnológica', 'CE-FIHR5', 'Analiza a partir de criterios éticos los avances científicos y tecnológicos con la finalidad de proteger la vida y la sostenibilidad del entorno natural.'),
('Secundaria', '3ro', 'Formación Integral Humana y Religiosa', 'BC3', 'Ambiental y de la Salud', 'CE-FIHR6', 'Desarrolla acciones de protección y cuidado al entorno natural, a partir de los valores de Jesús de Nazaret y otros líderes, en su familia, escuela y comunidad, a fin de fomentar el cuidado de la casa común creada por Dios para el disfrute de todos.')
ON CONFLICT (nivel, grado, asignatura, competencia_fundamental) 
DO UPDATE SET 
    codigo = EXCLUDED.codigo,
    descriptor = EXCLUDED.descriptor,
    bloque = EXCLUDED.bloque,
    updated_at = NOW();
